"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def HasCycle(head):
    if ((head is None) or (head.next is None)):
        return False
    slow = head
    fast = head
    while ((fast is not None) and (fast.next is not None)):
        slow = slow.next
        fast = fast.next.next
        if (slow == fast):
            return True
    return False


class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


# Build: 1 → 2 → 3 → 4
#              ↑     ↓
#              ← ← ← ←

A = Node(1)
B = Node(2)
C = Node(3)
D = Node(4)

A.next = B
B.next = C
C.next = D
D.next = B   # cycle here

print(HasCycle(A))   # True

X = Node(10)
Y = Node(20)
Z = Node(30)

X.next = Y
Y.next = Z

print(HasCycle(X))   # False

